from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    families = (
        ("row", lambda r, c: r),
        ("col", lambda r, c: c),
        ("diff", lambda r, c: c-r),
        ("sum", lambda r, c: r+c),
    )
    candidates = []
    for name, key in families:
        lines = {}
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v:
                    lines.setdefault(key(r, c), Counter())[v] += 1
        stripes = [(off, counts) for off, counts in lines.items()
                   if len(counts) == 1 and sum(counts.values()) >= 3]
        score = (len(stripes), sum(sum(counts.values()) for _, counts in stripes))
        candidates.append((score, name, stripes))

    _, orientation, stripes = max(candidates, key=lambda item: item[0])
    period = len(stripes)
    motif = [0] * period
    for offset, counts in stripes:
        motif[offset % period] = next(iter(counts))

    if orientation == "row":
        return [[motif[r % period] for _ in range(w)] for r in range(h)]
    if orientation == "col":
        return [[motif[c % period] for c in range(w)] for _ in range(h)]
    if orientation == "diff":
        return [[motif[(c-r) % period] for c in range(w)] for r in range(h)]
    return [[motif[(r+c) % period] for c in range(w)] for r in range(h)]

